// Account defines model for Account.
type Account struct {
	AccountId int64 `json:"account_id"`

	// AccountType Account semantic type. Owned and party accounts hold tracked household state; flow records carry categorized economic activity; system accounts are fixed Mina mechanics.
	AccountType AccountType `json:"account_type"`
	CreatedAt   time.Time   `json:"created_at"`

	// Currency NULL means the account is multi-currency. A code means every active journal and recurring-definition record for the account must use that currency.
	Currency *string `json:"currency,omitempty"`

	// Deletable Populated in listAccounts responses. True when the active account has no active dependent resources and can be tombstone-deleted.
	Deletable *bool `json:"deletable,omitempty"`

	// DisplayLabel Effective non-unique presentation label. An explicit override wins; otherwise Mina derives the final one or two FQN segments.
	DisplayLabel string `json:"display_label"`

	// DisplayLabelOverride Stored custom presentation label, or null when display_label is derived from the FQN.
	DisplayLabelOverride *string `json:"display_label_override"`
	ExternalId           *string `json:"external_id,omitempty"`
	ExternalSystem       *string `json:"external_system,omitempty"`
	Fqn                  string  `json:"fqn"`

	// HasCreditLimitHistory Populated in listAccounts responses. True when the account has active credit-limit history.
	HasCreditLimitHistory *bool      `json:"has_credit_limit_history,omitempty"`
	IsFeatured            bool       `json:"is_featured"`
	IsHidden              bool       `json:"is_hidden"`
	Level                 int        `json:"level"`
	Name                  string     `json:"name"`
	ParentFqn             *string    `json:"parent_fqn"`
	TombstonedAt          *time.Time `json:"tombstoned_at,omitempty"`
	UpdatedAt             time.Time  `json:"updated_at"`
}

// AccountBalance defines model for AccountBalance.
type AccountBalance struct {
	AccountId int64 `json:"account_id"`

	// CreditLimit JSON string, not a JSON number. Current credit limit in the account's single currency, when known, from the latest active credit-limit-history row with effective_date on or before the API runtime clock's local civil date. Responses use fixed-scale formatting with exactly 8 fractional digits.
	CreditLimit *string `json:"credit_limit,omitempty"`
	Currency    string  `json:"currency"`

	// CurrentBalance JSON string, not a JSON number. Posted plus pending aggregate DECIMAL(18,8) balance in this currency; cancelled and expected records excluded. Responses use fixed-scale formatting with exactly 8 fractional digits.
	CurrentBalance string `json:"current_balance"`

	// CurrentBalanceUsd JSON string, not a JSON number. Approximate USD-equivalent DECIMAL(18,8) aggregate using stored journal-record amount_usd values only; no query-time exchange-rate conversion is performed. Partial when unconverted_count is greater than zero. Responses use fixed-scale formatting with exactly 8 fractional digits.
	CurrentBalanceUsd string `json:"current_balance_usd"`

	// PostedBalance JSON string, not a JSON number. Posted-only aggregate DECIMAL(18,8) balance in this currency; cancelled and expected records excluded. Responses use fixed-scale formatting with exactly 8 fractional digits.
	PostedBalance string `json:"posted_balance"`

	// RemainingCredit JSON string, not a JSON number. Present only when `credit_limit` is present; bank-facing remaining credit derived as the current credit limit plus the signed `current_balance`, without clamping or absolute-value conversion. May be negative when the account is over limit. Responses use fixed-scale formatting with exactly 8 fractional digits.
	RemainingCredit *string `json:"remaining_credit,omitempty"`

	// UnconvertedCount Count of active non-cancelled records contributing to this balance row that do not have amount_usd.
	UnconvertedCount int64 `json:"unconverted_count"`
}

